# Types with no MIN/MAX (not orderable) or no equality (COUNT DISTINCT / GROUP BY), by the
# leading word of `information_schema.columns.data_type`.
_UNORDERABLE = ("map", "row", "json", "hyperloglog", "qdigest", "tdigest", "setdigest", "geometry")
_UNGROUPABLE = ("hyperloglog", "qdigest", "tdigest", "setdigest", "geometry")

_COLUMN_TYPES_SQL = (
    "SELECT column_name, data_type FROM information_schema.columns"
    " WHERE table_schema = :schema AND table_name = :table"
)


def _column_caps(conn: Any, schema: str, table: str) -> dict[str, ColumnCaps]:
    from sqlalchemy import text

    caps: dict[str, ColumnCaps] = {}
    for name, data_type in conn.execute(
        text(_COLUMN_TYPES_SQL), {"schema": schema, "table": table}
    ).all():
        head = str(data_type).split("(", 1)[0].strip().lower()
        caps[str(name)] = ColumnCaps(
            orderable=head not in _UNORDERABLE, groupable=head not in _UNGROUPABLE
        )
    return caps

