import pathlib
import re

BLOCK = re.compile(r"<<<<<<< HEAD\n(.*?)\|\|\|\|\|\|\| [^\n]*\n(.*?)=======\n(.*?)>>>>>>> origin/main\n", re.S)


def resolve(path: str, fn) -> None:
    p = pathlib.Path(path)
    s = p.read_text()
    s, n = BLOCK.subn(lambda m: fn(m.group(1), m.group(2), m.group(3)), s)
    assert "<<<<<<<" not in s, path
    p.write_text(s)
    print(path, n)


def guide(h: str, b: str, t: str) -> str:
    if not b.strip():
        return t + h  # MySQL row/section/table row, then Trino's
    if "Browsing for a run target" in h:
        return "### Browsing for a run target (Unity Catalog, PostgreSQL, MySQL, Trino, ADLS Gen2, S3)\n"
    if "There is no catalog level" in h:
        return (
            "  with. There is no catalog level: the connection pins one database. **MySQL / MariaDB**\n"
            "  works the same way, its schemas being the databases the user has privileges on, and\n"
            "  **Trino** inside the connection's catalog, listing what the cluster's access control\n"
            "  lets the user see.\n"
        )
    if "PostgreSQL `host` / `port`, Trino" in h:
        return (
            "`warehouse` / `properties` / `secret_property`, PostgreSQL / MySQL `host` / `port`, Trino\n"
            "`host` / `port` / `sslmode` / `ca_bundle` / `auth_type`, Airflow\n"
        )
    r = (
        t.replace("PostgreSQL / MySQL —", "PostgreSQL / MySQL / Trino —")
        .replace("PostgreSQL and MySQL are unaffected", "PostgreSQL, MySQL and Trino are unaffected")
        .replace("PostgreSQL/MySQL, the Parquet", "PostgreSQL/MySQL/Trino, the Parquet")
    )
    assert r != t, h
    return r


def matrix(h: str, b: str, t: str) -> str:
    if not b.strip():
        return t + h
    if h.startswith("| Check kind"):
        out = []
        for hl, tl in zip(h.splitlines(), t.splitlines(), strict=True):
            hc, tc = hl.split("|"), tl.split("|")
            tc.insert(6, hc[5])  # the Trino cell after MySQL's
            out.append("|".join(tc))
        return "\n".join(out) + "\n"
    if "SQL-datasource only" in h:
        return (
            "Custom SQL runs a SQL query, so it's **SQL-datasource only** (Snowflake, Unity Catalog, PostgreSQL,\n"
            "MySQL/MariaDB, Trino;\n"
        )
    if h.startswith("⁴"):
        return "⁴ PostgreSQL, MySQL and Trino keep no lineage log DataQ reads, so there is no warehouse-native pull; the\n"
    raise SystemExit(h)


resolve("docs/site/guides/datasources-checks.md", guide)
resolve("docs/site/reference/feature-matrix.md", matrix)

